package com.styleshop.order.model;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@Entity @Table(name="shop_orders") public class ShopOrder {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;private String username;private LocalDateTime createdAt;private BigDecimal totalAmount;private String status;@OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER)private List<OrderItem> items=new ArrayList<>();public Long getId(){return id;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public LocalDateTime getCreatedAt(){return createdAt;}public void setCreatedAt(LocalDateTime v){createdAt=v;}public BigDecimal getTotalAmount(){return totalAmount;}public void setTotalAmount(BigDecimal v){totalAmount=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public List<OrderItem> getItems(){return items;}}
